// Isolated Director + full board + remote viewport. All campaign/auth data are QA-only.
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
const dest=resolve(process.argv[2]||'');if(!process.argv[2])throw Error('Diretório novo obrigatório.');
const run=spawnSync(process.execPath,[new URL('./live-room-recovery-demo.mjs',import.meta.url).pathname,dest],{encoding:'utf8'});if(run.status)throw Error(run.stderr);const web=join(dest,'public');
const app=join(web,'campaign-director/dist/app.js');let source=readFileSync(app,'utf8');
source+=`\n// Seed a disposable script. The future consent below is fixture-only, never a production default.
import {imageKey as qaKey} from './cinematic-media.js?v=directorcinematic02';
const qaLoad=async(name,type)=>new Blob([await(await fetch('../../qa-media/'+name)).arrayBuffer()],{type}),qaBG=await qaLoad('palco.png','image/png'),qaLayer=await qaLoad('iris.png','image/png'),qaVideo=await qaLoad('iris.webm','video/webm'),qaFuture=new Blob([qaBG,new Uint8Array(512*1024)],{type:'image/png'});const qaHashes=await Promise.all([qaBG,qaLayer,qaVideo,qaFuture].map(qaKey));await cinematicImages.putAll(qaHashes.map((id,i)=>[id,[qaBG,qaLayer,qaVideo,qaFuture][i]]));
const qaOne={id:'entry',name:'Entrada no teatro',imageId:qaHashes[0],motion:'living',seconds:12,intensity:10,ending:'loop',hold:0,fadeIn:.1,fadeOut:.2},qaTwo={...qaOne,id:'stage',name:'O palco desperta',imageId:qaHashes[3],layers:[{id:'figure',name:'Figura de teste',imageId:qaHashes[1],x:.5,y:.7,scale:.35,parallax:1,visible:true,video:{mediaId:qaHashes[2],enabled:true,loop:true,rate:1,delay:0,end:'fallback',transparent:true}}]};
const qaScenes=[makeScene('A porta do teatro'),makeScene('O palco'),makeScene('Uma ramificação')];qaScenes[0].id='entry-scene';qaScenes[1].id='stage-scene';qaScenes[2].id='branch-scene';qaScenes[0].cinematic={version:1,items:[qaOne]};qaScenes[1].cinematic={version:1,items:[qaTwo],remotePrewarmIds:[qaTwo.id]};qaScenes[2].cinematic={version:1,items:[{...qaOne,id:'alternate-a',name:'Alternativa A'},{...qaOne,id:'alternate-b',name:'Alternativa B'}]};for(const [i,s]of qaScenes.entries())s.markdown='# '+s.title+'\\n\\n'+['A sala está silenciosa. Uma luz atravessa a porta do teatro. Apresente a entrada e observe a preparação da próxima cena.','A apresentação já pode reutilizar os arquivos recebidos. Esta rodada usa consentimento fictício previamente configurado.','Escolha uma principal. Nenhuma alternativa será antecipada automaticamente.'][i];
state.campaigns[0].pages=[{...state.campaigns[0].pages[0],id:'qa-script',title:'Teatro · roteiro fictício',folder:'Roteiro',scenes:qaScenes}];state.ui.campaignId=state.campaigns[0].id;state.ui.pageId='qa-script';state.ui.sceneId='entry-scene';state.ui.view='document';renderApp();persist();\n`;
writeFileSync(app,source);
writeFileSync(join(web,'director-qa.html'),`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><style>body{margin:0;background:#15120f;color:#dfd0b7;font:13px system-ui}nav{display:flex;gap:10px;align-items:center;padding:8px}button,select{padding:8px}iframe{border:0;display:block;width:1280px;height:950px}#player{width:390px;height:844px}iframe[hidden]{display:block;position:absolute;left:-10000px;top:100px}pre{white-space:pre-wrap}</style><nav><b>DIRECTOR-CINEMATIC · dados fictícios</b><button id="connect">Conectar mesa</button><select id="view"><option value="director">Director</option><option value="master">Quadro mestre</option><option value="player">Jogador mobile</option></select><button id="report">Ler diagnóstico</button><button id="reopen">Reabrir jogador</button><label>Orientação <select id="orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label><label><input type="checkbox" id="slow">Quadro lento</label></nav><p>Rede SIMULADA. Director, Wire, prova, mídia e CinematicFrame reais. Não homologa WebRTC ou aparelho físico.</p><iframe id="director" title="Director"></iframe><iframe id="master" title="Mestre" hidden></iframe><iframe id="player" title="Jogador mobile" hidden></iframe><pre id="result"></pre><script type="module">
const $=s=>document.querySelector(s),key=new URLSearchParams(location.search).get('case')||'director-'+crypto.randomUUID(),base='quadro/?case='+key+'&transport=simulated&visual=1';$('#director').src='campaign-director/dist/?case='+key;$('#master').src=base;$('#player').src=base+'&user=player-'+key;const master=$('#master').contentWindow,player=$('#player').contentWindow,sleep=ms=>new Promise(r=>setTimeout(r,ms)),until=async f=>{for(let i=0;i<400;i++){if(f())return;await sleep(30);}throw Error('QA timeout');};$('#connect').onclick=async()=>{await until(()=>master.document.querySelector('#masterStart')&&player.document.querySelector('#vwGo'));master.document.querySelector('#masterStart').click();await until(()=>master.document.querySelector('#shCodeB')?.textContent.length>6);player.document.querySelector('#vwRoom').value=master.document.querySelector('#shCodeB').textContent;player.document.querySelector('#vwGo').click();};$('#view').onchange=e=>{for(const id of ['director','master','player'])$('#'+id).hidden=id!==e.target.value;};$('#orientation').onchange=e=>{const landscape=e.target.value==='landscape';$('#player').style.width=(landscape?844:390)+'px';$('#player').style.height=(landscape?390:844)+'px';};$('#reopen').onclick=()=>{const url=new URL($('#player').contentWindow.location.href);if($('#slow').checked)url.searchParams.set('slow','1');else url.searchParams.delete('slow');$('#player').src='about:blank';setTimeout(()=>$('#player').src=url.href,50);};$('#report').onclick=()=>$('#result').textContent=JSON.stringify({master:master.CRIS_REMOTE_CINEMATICS?.diagnostics(),player:player.CRIS_REMOTE_CINEMATICS?.diagnostics(),videoCount:player.document.querySelectorAll('video').length},null,2);
</script></html>`);
const boardHTML=readFileSync(join(web,'quadro/index.html'),'utf8'),loadingMarkup=boardHTML.match(/<div id="crisLoading">.*?<\/div><\/div>/)[0],loadingStyle=boardHTML.match(/<style>body\.cris-loading[\s\S]*?<\/style>/)[0];
writeFileSync(join(web,'loading-qa.html'),`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>QA · carregamento do quadro</title><link rel="stylesheet" href="quadro/base.css"><link rel="stylesheet" href="quadro/Halloween2026-1.css"><link rel="stylesheet" href="quadro/board-room.css"><link rel="stylesheet" href="quadro/board-polish.css">${loadingStyle}<body class="ui cris-loading">${loadingMarkup}<script src="quadro/board-startup.js"></script><script>CRIS_BOARD_BOOT.stage('Recebendo imagens e organizando o quadro…');</script></body></html>`);
const simPath=join(web,'live-peer-simulated.js');writeFileSync(simPath,readFileSync(simPath,'utf8').replace("if(m.kind==='data'&&c.open)c.emit('data',m.data);","if(m.kind==='data'&&c.open){if(new URLSearchParams(location.search).has('slow')&&m.data?.kind==='chunk'&&!m.data.scope?.endsWith(':cinematic'))setTimeout(()=>{if(c.open)c.emit('data',m.data);},600);else c.emit('data',m.data);}"));
console.log(dest);
